import urllib.request,json,collections
with urllib.request.urlopen('http://127.0.0.1:17448/api/supervisor-watchdog/agent-assignments',timeout=5) as r:j=json.load(r)
cat=collections.Counter(); examples=[]
for a in j.get('assignments',[]):
 if a.get('state') in ('blocked','failed') and (a.get('dispatchSubmitAttempted') is True or (a.get('dispatchCount') or 0)>0):
  code=str(a.get('dispatchFailureCode') or a.get('lastDiagnostic') or '')
  cat[code[:100]]+=1
  if len(examples)<24:examples.append({'id':a.get('id'),'state':a.get('state'),'count':a.get('dispatchCount'),'attempted':a.get('dispatchSubmitAttempted'),'code':code[:90],'preflight':a.get('lastPreflightReason'),'hasFingerprint':bool(a.get('dispatchFingerprint'))})
print(json.dumps({'categories':dict(cat),'sample':examples,'readOnly':True},ensure_ascii=True)[:6000])
